{"command": "python3 -c "
import pandas as pd
df_imf = pd.read_excel('/root/data/imf_commodity_prices.xlsx', sheet_name='External')
gold_idx = -1
for i, col in enumerate(df_imf.iloc[0,:]):
    if 'Gold' in str(col) and 'troy ounce' in str(col):
        print(f'Found gold column at index {i}: {col}')
        gold_idx = i
if gold_idx != -1:
    print('Dates:', df_imf.iloc[2:, 0].head())
    print('Gold prices:', df_imf.iloc[2:, gold_idx].head())
""}

